\echo === FASE 2: PEDIDOS SETIEMBRE (18) ===
BEGIN;

ON CONFLICT (codigo_orden) DO NOTHING;

COMMIT;

\echo === Verificar pedidos setiembre ===
SELECT codigo_orden, producto_nombre, cantidad_solicitada, unidad_medida, monto_total, estado, formula_id, cliente_id
FROM pedidos_comerciales WHERE codigo_orden LIKE 'OP-202609%' ORDER BY codigo_orden;
SELECT COUNT(*) AS total_pedidos FROM pedidos_comerciales;